1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16		"unicode/utf8"
17	)
18	
19	// Status 表示样品所处的判定状态。
20	type Status string
21	
22	const (
23		// StatusPending 样品已录入，尚未确认判定结果。
24		StatusPending Status = "pending"
25		// StatusConfirmed 样品已确认，判定结果已保存。
26		StatusConfirmed Status = "confirmed"
27		// StatusVoided 样品已作废，保留记录但不能再确认。
28		StatusVoided Status = "voided"
29	)
30	
31	var (
32		ErrClosed             = errors.New("water: 数据存放已关闭")
33		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
34		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
35		ErrUnknownPoint       = errors.New("water: 采样点未登记")
36		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
37		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
38		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
39		ErrUnknownSample      = errors.New("water: 样品编号不存在")
40		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
41		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
42		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
43		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
44		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
45		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
46		ErrInvalidText        = errors.New("water: 采样点编号、名称、项目名、样品编号或作废原因不是合法的 UTF-8 文本")
47		ErrCorruptRecord      = errors.New("water: 本地数据中存在缺少原测量、测量项目重复、测量项目与逐项判定对应不上或超标标记与保存的判定依据不一致的损坏样品记录")
48	)
49	
50	// SamplingPoint 是按编号唯一登记的采样点。
51	type SamplingPoint struct {
52		ID   string `json:"id"`
53		Name string `json:"name"`
54	}
55	
56	// Limit 是某采样点某测量项目的一版数值上限。
57	type Limit struct {
58		PointID   string    `json:"pointId"`
59		Item      string    `json:"item"`
60		Value     float64   `json:"value"`
61		Effective time.Time `json:"effective"`
62	}
63	
64	// Measurement 是样品中一个项目的测量值。
65	type Measurement struct {
66		Item  string  `json:"item"`
67		Value float64 `json:"value"`
68	}
69	
70	// ItemResult 是确认后单个项目的判定结果。
71	type ItemResult struct {
72		Item           string    `json:"item"`
73		Value          float64   `json:"value"`
74		Limit          float64   `json:"limit"`
75		LimitEffective time.Time `json:"limitEffective"`
76		Exceeded       bool      `json:"exceeded"`
77	}
78	
79	// Sample 是一份从录入、确认到作废的样品记录。
80	type Sample struct {
81		ID           string        `json:"id"`
82		PointID      string        `json:"pointId"`
83		SampledAt    time.Time     `json:"sampledAt"`
84		Measurements []Measurement `json:"measurements"`
85		Status       Status        `json:"status"`
86		Results      []ItemResult  `json:"results,omitempty"`
87		Exceeded     bool          `json:"exceeded"`
88		VoidReason   string        `json:"voidReason,omitempty"`
89	}
90	
91	// diskState 是落盘的完整数据。
92	type diskState struct {
93		Points  map[string]SamplingPoint `json:"points"`
94		Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
95		Samples map[string]*Sample       `json:"samples"`
96	}
97	
98	// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
99	// 用单字符拼接成键时不同组合撞成同一组。
100	type limitGroup struct {
101		pointID string
102		item    string
103	}
104	
105	// Store 是绑定到某个本地目录的取样判定数据存放。
106	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
107	type Store struct {
108		mu      sync.Mutex
109		dir     string
110		file    string
111		closed  bool
112		points  map[string]SamplingPoint
113		limits  map[limitGroup][]Limit // 按生效时间升序
114		samples map[string]*Sample
115	}
116	
117	// Open 打开（必要时创建）dir 下的本地数据存放。
118	//
119	// 读入时先核对每份样品都至少保留一个原测量项目：Measurements 为空列表、保存为
120	// null 或整个字段缺失都算样品内容残缺，即使编号、采样点、采样时间齐全也不能
121	// 接受；这条要求对任何状态的样品都生效，包括待判定样品，以及待判定后直接作废、
122	// 不再参与有效判定的样品——不能因为它没有历史结论就放过内容丢失；原测量为空但
123	// 残留逐项判定的记录也不能反过来用判定内容填补原测量。再核对原测量项目名：
124	// 同一个测量项目名在一份样品里只能出现一次，不依赖两条记录是否相邻，也不因
125	// 数值相同（包括两个零）而放行。再核对每份已保存结论的样品：已确认样品，以及
126	// 已确认后作废、逐项依据仍保留在 Results 中的样品，其原测量项目与逐项判定
127	// 必须按项目名完整一一对应；判定里同一项目不能出现两次；每个测量项目必须且
128	// 只能有一条判定，判定里也不能出现原测量没有的项目；对应项目的判定测量值必须
129	// 与原测量值一致（零是合法测量值，不会被当成缺项）。两个列表排列顺序不同不
130	// 影响对应，成功读入后测量与判定各自保留原顺序。最后核对超标标记与该样品
131	// 已保存的判定依据一致：每条判定的超标标记必须严格符合该条保存的测量值与
132	// 上限——测量值严格大于上限才是超标，小于或等于（包括等于、零与负数的合法
133	// 组合）都应为达标；整份样品的超标标记必须与逐项结论一致，任一项超标就应为
134	// 真、全部达标就应为假。只核对本文件里已保存的依据，不重新选择当前限值、
135	// 不重做判定。任一份样品对不上，整次打开以可被 errors.Is(err, ErrCorruptRecord)
136	// 识别的错误失败，返回 nil 数据存放，错误信息点到具体样品编号与缺少原测量的
137	// 原因（或具体项目）；单项超标标记有误时点到具体项目，整份标记有误时说明它
138	// 与逐项结论不一致；不会静默跳过问题样品、不会择一保留或合并重复测量、不会
139	// 补出缺失测量或判定、不会修正超标标记或重新判定、不会把它改成另一种状态、
140	// 也不会把拒绝推迟到请求确认时，更不会改写原文件。待判定样品没有判定记录、
141	// 待判定后作废的样品没有历史依据，均属正常，只要原测量完整就照常读入。
142	// 完整记录原样读入，已保存的上限、生效时间、逐项结论与整份超标标记保留，不因
143	// 后来新增或补录的限值而拒绝或重新计算。没有任何样品的新数据目录，以及样品
144	// 集合为空的已有数据，都照常打开。
145	func Open(dir string) (*Store, error) {
146		if strings.TrimSpace(dir) == "" {
147			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
148		}
149		if err := os.MkdirAll(dir, 0o755); err != nil {
150			return nil, err
151		}
152		s := &Store{
153			dir:     dir,
154			file:    filepath.Join(dir, "water-data.json"),
155			points:  map[string]SamplingPoint{},
156			limits:  map[limitGroup][]Limit{},
157			samples: map[string]*Sample{},
158		}
159		data, err := os.ReadFile(s.file)
160		if errors.Is(err, fs.ErrNotExist) {
161			return s, nil
162		}
163		if err != nil {
164			return nil, err
165		}
166		var st diskState
167		if err := json.Unmarshal(data, &st); err != nil {
168			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
169		}
170		if st.Points != nil {
171			s.points = st.Points
172		}
173		if st.Limits != nil {
174			// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
175			// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
176			// 让曾经被错误合并的组在重新打开时也能各自归位。
177			for _, versions := range st.Limits {
178				for _, lim := range versions {
179					g := limitGroup{pointID: lim.PointID, item: lim.Item}
180					s.limits[g] = append(s.limits[g], lim)
181				}
182			}
183			for g, versions := range s.limits {
184				sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
185				s.limits[g] = versions
186			}
187		}
188		if st.Samples != nil {
189			// 逐份校验后才整体接收：任何状态的样品都必须至少保留一个原测量，
190			// 原测量项目名重复也都是损坏，带结论的样品还要求逐项判定与原测量
191			// 完整对应。任一份样品不通过，整次打开都失败，不返回数据存放对象，
192			// 也不静默跳过、择一保留、补测量、补判定或回写原文件。
193			ids := make([]string, 0, len(st.Samples))
194			for id := range st.Samples {
195				ids = append(ids, id)
196			}
197			sort.Strings(ids)
198			for _, id := range ids {
199				if err := validateLoadedSample(id, st.Samples[id]); err != nil {
200					return nil, err
201				}
202			}
203			s.samples = st.Samples
204		}
205		return s, nil
206	}
207	
208	// validateLoadedSample 校验一份从本地文件读入的样品记录。
209	//
210	// 无论样品处于什么状态，都必须至少保留一个原测量项目：Measurements 为空列表、
211	// 保存为 null 或整个字段在文件中缺失，都表示样品内容残缺，即使编号、采样点、
212	// 采样时间齐全也不能接受。待判定样品与待判定后作废（Results 为空、没有历史
213	// 判定依据）的样品同样适用，不能因为它们不再参与有效判定就放过内容丢失；
214	// 原测量为空但残留逐项判定的记录也不能反过来用判定内容填补原测量。
215	//
216	// 原测量项目名也不允许重复：同一个项目名在 Measurements 中只能出现一次，按
217	// 文件中保存的完整项目名判断，不依赖两条记录是否相邻，也不因数值相同（含两个
218	// 零）而放行。待判定样品与待判定后作废的样品虽然没有逐项结果，仍要过这一关；
219	// 它们没有判定记录本身不是损坏，测量项目不重复即正常读入，不会被要求已经有
220	// 判定依据。
221	//
222	// 带结论的样品还要满足：已确认样品，以及已确认后作废、Results 中仍保留历史依据
223	// 的样品，其原测量项目与逐项判定必须按项目名一一对应；判定中同一项目不能出现
224	// 两次；每个测量项目必须且只能有一条判定记录，判定中也不能出现原测量没有的
225	// 项目；对应项目的判定测量值必须与原测量值逐位一致（零是合法测量值，按 map
226	// 中是否存在该项目判断，不把零当成缺项）。项目按名称对应，与两个列表的排列
227	// 顺序无关。
228	//
229	// 对应关系通过后，超标标记还必须与这份样品已保存的判定依据一致：每条判定的
230	// Exceeded 必须严格等于“该条保存的测量值 > 该条保存的上限”，测量值小于或等于
231	// 上限（含等于、零或负数的合法数值组合）都应为达标；整份样品的 Exceeded 必须
232	// 等于“是否有任一项超标”，全部达标则应为假。这里只核对已保存的依据本身，
233	// 不按当前限值重新选择上限、不重做判定，因此后来补录的限值即使会使结论改变，
234	// 也不影响读入。单项标记有误点名项目；单项都正确而整份标记相反，说明它与逐项
235	// 结论不一致。待判定样品与待判定后直接作废、没有历史依据的样品不要求有结论，
236	// 也不核对超标标记。key 是落盘 map 中的样品编号，用于在记录本身残缺（如空记录）
237	// 时仍能指出是哪份样品。
238	func validateLoadedSample(key string, smp *Sample) error {
239		if smp == nil {
240			return fmt.Errorf("%w: 样品 %s 的记录为空", ErrCorruptRecord, key)
241		}
242		id := smp.ID
243		if id == "" {
244			id = key
245		}
246		// 至少一个原测量项目是任何状态样品（含待判定、待判定后作废）的读入前提：
247		// 空列表、null 或字段缺失都算内容残缺，必须在打开时整次拒绝，不能等请求
248		// 确认时才暴露，也不能用残留的逐项判定反填原测量。
249		if len(smp.Measurements) == 0 {
250			return fmt.Errorf("%w: 样品 %s 缺少原测量：原测量项目列表为空、为 null 或字段缺失",
251				ErrCorruptRecord, id)
252		}
253		// 原测量项目名去重适用于任何状态的样品（含待判定、待判定后作废）：
254		// 重复测量是记录本身损坏，不能等确认保存判定依据时才暴露。
255		meas := make(map[string]float64, len(smp.Measurements))
256		for _, m := range smp.Measurements {
257			if _, ok := meas[m.Item]; ok {
258				return fmt.Errorf("%w: 样品 %s 的测量项目 %s 重复", ErrCorruptRecord, id, m.Item)
259			}
260			meas[m.Item] = m.Value
261		}
262		// 待判定样品与待判定后作废（没有历史依据）的样品没有逐项判定，
263		// 原测量不重复即为正常记录，不要求它们已经有结论。
264		if smp.Status != StatusConfirmed && len(smp.Results) == 0 {
265			return nil
266		}
267		got := make(map[string]float64, len(smp.Results))
268		for _, r := range smp.Results {
269			if _, ok := got[r.Item]; ok {
270				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定记录重复", ErrCorruptRecord, id, r.Item)
271			}
272			got[r.Item] = r.Value
273		}
274		// 缺项或判定测量值与原测量不一致（按测量列表顺序报告，保持信息稳定）。
275		for _, m := range smp.Measurements {
276			rv, ok := got[m.Item]
277			if !ok {
278				return fmt.Errorf("%w: 样品 %s 缺少项目 %s 的判定记录", ErrCorruptRecord, id, m.Item)
279			}
280			if rv != m.Value {
281				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定测量值 %g 与原测量值 %g 不一致",
282					ErrCorruptRecord, id, m.Item, rv, m.Value)
283			}
284		}
285		// 判定中出现原测量没有的项目。
286		for _, r := range smp.Results {
287			if _, ok := meas[r.Item]; !ok {
288				return fmt.Errorf("%w: 样品 %s 的判定记录出现了原测量中没有的项目 %s",
289					ErrCorruptRecord, id, r.Item)
290			}
291		}
292		// 超标标记必须与这份样品已保存的判定依据一致。只按每条记录保存的测量值与
293		// 上限判断：严格大于才超标，小于或等于（含等于、零或负数的合法组合）都为
294		// 达标；不重新选择当前限值。单项标记与依据矛盾时点名该项目，整份标记与
295		// 逐项结论矛盾时单独说明。整份样品只允许一种矛盾先报出，但两者都会拒绝。
296		anyExceeded := false
297		for _, r := range smp.Results {
298			want := r.Value > r.Limit
299			if r.Exceeded != want {
300				return fmt.Errorf("%w: 样品 %s 的项目 %s 超标标记与保存的判定依据不一致：测量值 %g %s 上限 %g 应判为%s，却保存为%s",
301					ErrCorruptRecord, id, r.Item, r.Value, cmpText(r.Value, r.Limit), r.Limit,
302					judgementText(want), judgementText(r.Exceeded))
303			}
304			if want {
305				anyExceeded = true
306			}
307		}
308		if smp.Exceeded != anyExceeded {
309			return fmt.Errorf("%w: 样品 %s 的整份超标标记与逐项判定结论不一致：逐项判定中%s，整份标记却保存为%s",
310				ErrCorruptRecord, id,
311				overallText(anyExceeded), judgementText(smp.Exceeded))
312		}
313		return nil
314	}
315	
316	// cmpText 生成比较词，仅用于损坏记录的错误信息。
317	func cmpText(value, limit float64) string {
318		switch {
319		case value > limit:
320			return "大于"
321		case value < limit:
322			return "小于"
323		default:
324			return "等于"
325		}
326	}
327	
328	// judgementText 把超标标记翻成判定结论文本，仅用于损坏记录的错误信息。
329	func judgementText(exceeded bool) string {
330		if exceeded {
331			return "超标"
332		}
333		return "达标"
334	}
335	
336	// overallText 描述逐项判定汇总后的情况，仅用于损坏记录的错误信息。
337	func overallText(anyExceeded bool) string {
338		if anyExceeded {
339			return "存在超标项，整份应判为超标"
340		}
341		return "全部项目达标，整份应判为达标"
342	}
343	
344	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
345	func (s *Store) Close() error {
346		s.mu.Lock()
347		defer s.mu.Unlock()
348		if s.closed {
349			return nil
350		}
351		s.closed = true
352		return nil
353	}
354	
355	func clean(s string) string { return strings.TrimSpace(s) }
356	
357	// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
358	// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
359	func diskLimitKey(pointID, item string) string {
360		return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
361	}
362	
363	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
364	
365	// invalidUTF8 报告文本是否无法作为合法 UTF-8 原样保存。必须在任何处理之前检查
366	// 提交的原始文本：落盘 JSON 会把非法字节（孤立的 0xFF、0xFE、不完整的多字节
367	// 序列等）静默替换成 U+FFFD，返回记录与保存内容会因此对不上，两个不同编号也
368	// 可能变成同一文本。真正的 U+FFFD（“�”）以及中文、U+0000 等都是合法字符，
369	// 不在拒绝之列；只在去首尾空白之外不做任何字符替换或归一化。
370	func invalidUTF8(s string) bool { return !utf8.ValidString(s) }
371	
372	func (s *Store) checkOpenLocked() error {
373		if s.closed {
374			return ErrClosed
375		}
376		return nil
377	}
378	
379	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
380	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
381	func (s *Store) persistLocked() error {
382		diskLimits := make(map[string][]Limit, len(s.limits))
383		for g, versions := range s.limits {
384			diskLimits[diskLimitKey(g.pointID, g.item)] = versions
385		}
386		data, err := json.MarshalIndent(diskState{
387			Points:  s.points,
388			Limits:  diskLimits,
389			Samples: s.samples,
390		}, "", "  ")
391		if err != nil {
392			return err
393		}
394		tmp := s.file + ".tmp"
395		if err := os.WriteFile(tmp, data, 0o644); err != nil {
396			return err
397		}
398		return os.Rename(tmp, s.file)
399	}
400	
401	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
402	// 保存和比较均使用处理后的文本；重复编号拒绝。
403	// 编号和名称必须都是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE 字节
404	// 或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
405	// 拒绝，不占用编号、不改动任何已有采样点；即使另一项为空白，或编号已登记而
406	// 这次名称含非法字节，也报告编码错误。真正的 U+FFFD（“�”）、中文和文本内部
407	// 的 U+0000 仍是合法字符。
408	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
409		s.mu.Lock()
410		defer s.mu.Unlock()
411		if err := s.checkOpenLocked(); err != nil {
412			return SamplingPoint{}, err
413		}
414		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
415		// 静默替换成 U+FFFD，登记“成功”后保存的编号或名称就会与填写内容对不上，
416		// 两个不同编号（如末尾分别带孤立 0xFF、0xFE）还可能保存成同一编号；
417		// 只有整次拒绝才能保证采样点身份在保存前后一致。
418		if invalidUTF8(id) || invalidUTF8(name) {
419			return SamplingPoint{}, ErrInvalidText
420		}
421		id, name = clean(id), clean(name)
422		if id == "" || name == "" {
423			return SamplingPoint{}, ErrEmptyField
424		}
425		if _, ok := s.points[id]; ok {
426			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
427		}
428		p := SamplingPoint{ID: id, Name: name}
429		s.points[id] = p
430		if err := s.persistLocked(); err != nil {
431			delete(s.points, id)
432			return SamplingPoint{}, err
433		}
434		return p, nil
435	}
436	
437	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
438	// 采样点编号和项目名必须是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE
439	// 字节或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
440	// 拒绝，不新增版本、不占用生效时间；真正的 U+FFFD（“�”）、中文和文本内部的
441	// U+0000 仍是合法字符。即使同次请求还存在采样点未登记、数值不是有限数或
442	// 生效时间缺失的问题，也报告文本编码错误。
443	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
444	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
445		s.mu.Lock()
446		defer s.mu.Unlock()
447		if err := s.checkOpenLocked(); err != nil {
448			return Limit{}, err
449		}
450		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
451		// 静默替换成 U+FFFD，登记“成功”后保存的项目名就会与填写内容对不上，
452		// 限值也不再属于实际填写的采样点和项目；只有整次拒绝才能保证一致。
453		if invalidUTF8(pointID) || invalidUTF8(item) {
454			return Limit{}, ErrInvalidText
455		}
456		pointID, item = clean(pointID), clean(item)
457		if pointID == "" || item == "" {
458			return Limit{}, ErrEmptyField
459		}
460		if _, ok := s.points[pointID]; !ok {
461			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
462		}
463		if !finite(value) {
464			return Limit{}, ErrInvalidValue
465		}
466		if effective.IsZero() {
467			return Limit{}, ErrInvalidTime
468		}
469		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
470		g := limitGroup{pointID: pointID, item: item}
471		versions := s.limits[g]
472		for _, v := range versions {
473			if v.Effective.Equal(lim.Effective) {
474				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
475			}
476		}
477		old := s.limits[g]
478		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
479		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
480		versions = make([]Limit, len(old)+1)
481		copy(versions, old)
482		versions[len(old)] = lim
483		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
484		s.limits[g] = versions
485		if err := s.persistLocked(); err != nil {
486			s.limits[g] = old
487			return Limit{}, err
488		}
489		return lim, nil
490	}
491	
492	// SubmitSample 录入一份样品，初始为待判定状态。
493	// 样品编号、采样点编号和每个项目名必须是合法的 UTF-8 文本：任一字段含孤立的
494	// 0xFF、0xFE 字节或不完整的多字节序列等无法原样保存的内容时，整份提交以
495	// ErrInvalidText 拒绝，不留部分记录，也不占用编号；真正的 U+FFFD（“�”）
496	// 仍是合法字符。再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
497	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
498	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
499		s.mu.Lock()
500		defer s.mu.Unlock()
501		if err := s.checkOpenLocked(); err != nil {
502			return Sample{}, err
503		}
504		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
505		// 静默替换成 U+FFFD，只有整份拒绝才能保证返回记录、按点查看与保存数据一致。
506		// 即使编号已被已有样品占用、非法项目排在最后，或提交同时存在其它内容问题，
507		// 也必须报告编码问题：不能归为未知采样点、项目重复或同编号冲突，更不能走
508		// 重复录入成功的分支。
509		if invalidUTF8(id) || invalidUTF8(pointID) {
510			return Sample{}, ErrInvalidText
511		}
512		for _, m := range measurements {
513			if invalidUTF8(m.Item) {
514				return Sample{}, ErrInvalidText
515			}
516		}
517		id, pointID = clean(id), clean(pointID)
518		if id == "" || pointID == "" {
519			return Sample{}, ErrEmptyField
520		}
521		if sampledAt.IsZero() {
522			return Sample{}, ErrInvalidTime
523		}
524		if len(measurements) == 0 {
525			return Sample{}, ErrNoMeasurements
526		}
527		ms := make([]Measurement, len(measurements))
528		seen := make(map[string]float64, len(measurements))
529		for i, m := range measurements {
530			item := clean(m.Item)
531			if item == "" {
532				return Sample{}, ErrEmptyField
533			}
534			if !finite(m.Value) {
535				return Sample{}, ErrInvalidValue
536			}
537			if _, dup := seen[item]; dup {
538				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
539			}
540			seen[item] = m.Value
541			ms[i] = Measurement{Item: item, Value: m.Value}
542		}
543		sampledAt = sampledAt.UTC()
544	
545		if existing, ok := s.samples[id]; ok {
546			if sameSampleContent(existing, pointID, sampledAt, seen) {
547				return copySample(existing), nil
548			}
549			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
550		}
551		if _, ok := s.points[pointID]; !ok {
552			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
553		}
554		smp := &Sample{
555			ID:           id,
556			PointID:      pointID,
557			SampledAt:    sampledAt,
558			Measurements: ms,
559			Status:       StatusPending,
560		}
561		s.samples[id] = smp
562		if err := s.persistLocked(); err != nil {
563			delete(s.samples, id)
564			return Sample{}, err
565		}
566		return copySample(smp), nil
567	}
568	
569	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
570		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
571			return false
572		}
573		for _, m := range s.Measurements {
574			v, ok := ms[m.Item]
575			if !ok || v != m.Value {
576				return false
577			}
578		}
579		return true
580	}
581	
582	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
583	// 测量值大于上限才超标，任一项目超标则整份样品超标。
584	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
585	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
586	func (s *Store) Confirm(id string) (Sample, error) {
587		s.mu.Lock()
588		defer s.mu.Unlock()
589		if err := s.checkOpenLocked(); err != nil {
590			return Sample{}, err
591		}
592		id = clean(id)
593		if id == "" {
594			return Sample{}, ErrEmptyField
595		}
596		smp, ok := s.samples[id]
597		if !ok {
598			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
599		}
600		switch smp.Status {
601		case StatusVoided:
602			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
603		case StatusConfirmed:
604			return copySample(smp), nil
605		}
606	
607		results := make([]ItemResult, 0, len(smp.Measurements))
608		exceeded := false
609		for _, m := range smp.Measurements {
610			lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
611			if !ok {
612				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
613			}
614			ex := m.Value > lim.Value
615			if ex {
616				exceeded = true
617			}
618			results = append(results, ItemResult{
619				Item:           m.Item,
620				Value:          m.Value,
621				Limit:          lim.Value,
622				LimitEffective: lim.Effective,
623				Exceeded:       ex,
624			})
625		}
626		smp.Results = results
627		smp.Exceeded = exceeded
628		smp.Status = StatusConfirmed
629		if err := s.persistLocked(); err != nil {
630			smp.Results = nil
631			smp.Exceeded = false
632			smp.Status = StatusPending
633			return Sample{}, err
634		}
635		return copySample(smp), nil
636	}
637	
638	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
639	// 采样时间恰好等于生效时间时使用该版新值。
640	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
641		best := -1
642		for i, v := range versions {
643			if v.Effective.After(at) {
644				break
645			}
646			best = i
647		}
648		if best < 0 {
649			return Limit{}, false
650		}
651		return versions[best], true
652	}
653	
654	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
655	// 作废原因必须是合法的 UTF-8 文本：原始原因含孤立的 0xFF、0xFE 字节或不完整
656	// 的多字节序列等无法原样保存的内容时，本次作废整体以 ErrInvalidText 拒绝，
657	// 返回空样品，不删除或替换任何字节、不改动样品状态与已有原因；即使样品编号
658	// 不存在，或样品已作废而这次原因与原原因不同，也报告文本编码错误，而不是
659	// 样品不存在或原因冲突（数据存放已关闭时仍返回 ErrClosed）。真正的 U+FFFD
660	// （“�”）、中文、表情和文本内部的 U+0000 仍是合法字符。作废后保留测量、原因
661	// 和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
662	func (s *Store) Void(id, reason string) (Sample, error) {
663		s.mu.Lock()
664		defer s.mu.Unlock()
665		if err := s.checkOpenLocked(); err != nil {
666			return Sample{}, err
667		}
668		// 在去首尾空白、查找样品和比对原因等任何处理之前检查原始原因：落盘 JSON
669		// 会把非法 UTF-8 静默替换成 U+FFFD，作废“成功”后当场返回的原因仍带原始
670		// 字节，保存与重开后却变成替换字符，同一记录前后对不上，再次提交原原因
671		// 还会被误判成原因冲突；只有整次拒绝才能保证原因在保存前后一致。
672		if invalidUTF8(reason) {
673			return Sample{}, ErrInvalidText
674		}
675		id, reason = clean(id), clean(reason)
676		if id == "" || reason == "" {
677			return Sample{}, ErrEmptyField
678		}
679		smp, ok := s.samples[id]
680		if !ok {
681			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
682		}
683		if smp.Status == StatusVoided {
684			if smp.VoidReason == reason {
685				return copySample(smp), nil
686			}
687			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
688		}
689		oldStatus := smp.Status
690		smp.Status = StatusVoided
691		smp.VoidReason = reason
692		if err := s.persistLocked(); err != nil {
693			smp.Status = oldStatus
694			smp.VoidReason = ""
695			return Sample{}, err
696		}
697		return copySample(smp), nil
698	}
699	
700	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
701	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
702		s.mu.Lock()
703		defer s.mu.Unlock()
704		if err := s.checkOpenLocked(); err != nil {
705			return nil, err
706		}
707		return s.pointSamplesLocked(clean(pointID), func(*Sample) bool { return true }), nil
708	}
709	
710	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
711	// 没有已确认且未作废的样品时 ok 为 false。
712	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
713		s.mu.Lock()
714		defer s.mu.Unlock()
715		if err := s.checkOpenLocked(); err != nil {
716			return Sample{}, false, err
717		}
718		list := s.pointSamplesLocked(clean(pointID), func(smp *Sample) bool {
719			return smp.Status == StatusConfirmed
720		})
721		if len(list) == 0 {
722			return Sample{}, false, nil
723		}
724		return list[0], true, nil
725	}
726	
727	// pointSamplesLocked 收集某采样点符合 keep 的样品，逐份复制后按统一规则排列，
728	// 供 ListByPoint 与 LatestResult 共用，保证两种查询对同一批样品的先后判断一致。
729	// 调用方须已持有锁；pointID 须已做首尾空白处理。
730	func (s *Store) pointSamplesLocked(pointID string, keep func(*Sample) bool) []Sample {
731		var list []Sample
732		for _, smp := range s.samples {
733			if smp.PointID == pointID && keep(smp) {
734				list = append(list, copySample(smp))
735			}
736		}
737		sortSamples(list)
738		return list
739	}
740	
741	func sortSamples(list []Sample) {
742		sort.Slice(list, func(i, j int) bool {
743			a, b := list[i], list[j]
744			if !a.SampledAt.Equal(b.SampledAt) {
745				return a.SampledAt.After(b.SampledAt)
746			}
747			return a.ID < b.ID
748		})
749	}
750	
751	func copySample(s *Sample) Sample {
752		c := *s
753		c.Measurements = append([]Measurement(nil), s.Measurements...)
754		c.Results = append([]ItemResult(nil), s.Results...)
755		return c
756	}
757

