1126					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
1127					Measurements: []Measurement{{Item: openPH, Value: 9}},
1128					Status:       StatusVoided, VoidReason: "复测确认样品污染", Exceeded: false,
1129					Results: []ItemResult{
1130						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
1131					},
1132				},
1133			},
1134		})
1135		assertOpenRejectsWholeFlag(t, dir, "S1")
1136	}
1137	
1138	// 一个文件里其他样品正常，也不能只跳过标记矛盾的样品继续打开。
1139	func TestOpenFlagContradictionRejectsWholeFile(t *testing.T) {
1140		dir := t.TempDir()
1141		writeDiskFile(t, dir, diskState{
1142			Points: openPoints(),
1143			Samples: map[string]*Sample{
1144				// 完整、正常的已确认样品。
1145				"S-GOOD": {
1146					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
1147					Measurements: []Measurement{{Item: openPH, Value: 7}},
1148					Status:       StatusConfirmed, Exceeded: false,
1149					Results: []ItemResult{
