1220					Measurements: []Measurement{{Item: openPH, Value: 9}},
1221					Status:       StatusConfirmed, Exceeded: true,
1222					Results: []ItemResult{
1223						{Item: openPH, Value: 9, Limit: 100, LimitEffective: at(2, 0), Exceeded: true},
1224					},
1225				},
1226			},
1227		})
1228		assertOpenRejects(t, dir, "S1", openPH, false)
1229	}
1230	
1231	// 待判定样品没有判定依据，其整份超标标记零值 false 不参与核对，照常读入。
1232	func TestOpenPendingWholeFlagNotChecked(t *testing.T) {
1233		dir := t.TempDir()
1234		writeDiskFile(t, dir, diskState{
1235			Points: openPoints(),
1236			Samples: map[string]*Sample{
1237				"S1": {
