1243		})
1244		s, err := Open(dir)
1245		if err != nil {
1246			t.Fatalf("待判定样品没有判定依据，不应核对超标标记: %v", err)
1247		}
1248		defer s.Close()
1249		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
1250			t.Fatalf("待判定样品不能成为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
1251		}
1252	}
1253	
1254	// 多项样品中只有一项标记相反：整次失败并点名出问题的项目，
1255	// 且不改动原文件中的任何标记。
1256	func TestOpenOneWrongItemFlagAmongMany(t *testing.T) {
