		t.Fatalf("待判定样品不能成为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
	}
}

// 多项样品中只有一项标记相反：整次失败并点名出问题的项目，
// 且不改动原文件中的任何标记。
func TestOpenOneWrongItemFlagAmongMany(t *testing.T) {
	dir := t.TempDir()
	results := []ItemResult{
		{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
